// main.rs
use aws_sdk_dynamodb::{types::AttributeValue, Client};
use lambda_runtime::{run, service_fn, Error, LambdaEvent};
use serde_json::{json, Value};
use std::collections::HashMap;
use std::env;

#[tokio::main]
async fn main() -> Result<(), Error> {
    let config = aws_config::load_from_env().await;
    let ddb = Client::new(&config);
    run(service_fn(|event: LambdaEvent<Value>| handler(&ddb, event))).await
}

async fn handler(ddb: &Client, event: LambdaEvent<Value>) -> Result<Value, Error> {
    let table = env::var("TABLE_NAME")?;
    let item_val = event.payload["item"].as_object().ok_or("missing item")?;
    let mut item: HashMap<String, AttributeValue> = HashMap::new();
    for (k, v) in item_val {
        let av = match v {
            Value::String(s) => AttributeValue::S(s.clone()),
            Value::Number(n) => AttributeValue::N(n.to_string()),
            Value::Bool(b) => AttributeValue::Bool(*b),
            _ => AttributeValue::S(v.to_string()),
        };
        item.insert(k.clone(), av);
    }
    ddb.put_item().table_name(&table).set_item(Some(item)).send().await?;
    Ok(json!({ "statusCode": 200, "body": "Item stored" }))
}
